/* ---------- chat ---------- */
function addMsg(cls,text){
  const div=document.createElement('div');
  div.className='msg '+cls; div.innerHTML=render(text);
  $('chatCol').appendChild(div); $('chat').scrollTop=$('chat').scrollHeight;
  return div;
}
function addChip(cls,text){
  const div=document.createElement('div');
  div.className='chip '+cls; div.textContent=text;
  $('chatCol').appendChild(div); $('chat').scrollTop=$('chat').scrollHeight;
}
function sendChat(){
  const text=$('input').value.trim(); if(!text)return;
  addMsg('user',text); $('input').value=''; $('sendBtn').disabled=true; curBot=null;
  pywebview.api.send(text).then(ok=>{
    if(!ok){addChip('error','上一条还在处理中');$('sendBtn').disabled=false;}
  });
}
$('input').addEventListener('keydown',e=>{
  if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChat();}
});

