/* 设置抽屉：localStorage 持久化 + 点击外部自动收起（LCA Layout.tsx） */
function setSettingsOpen(v){
  $('settingsMenu').classList.toggle('open',v);
  $('settingsChev').classList.toggle('up',v);
  localStorage.setItem(SETTINGS_KEY,v?'1':'0');
}
$('settingsToggle').onclick=()=>{
  setSettingsOpen(!$('settingsMenu').classList.contains('open'));
};
document.addEventListener('pointerdown',e=>{
  const m=$('settingsMenu');
  if(!m.classList.contains('open'))return;
  if(!$('settingsMenu').contains(e.target)&&!$('settingsToggle').contains(e.target)
     &&!$('themeToggle').contains(e.target))
    setSettingsOpen(false);
});

/* ---------- 主题（深色 / 浅色 / 自动跟随系统，三档循环） ---------- */
const THEME_KEY='codeagent-theme';
const THEME_ORDER=['dark','light','auto'];
const THEME_LABEL={dark:'深色',light:'浅色',auto:'自动（跟随系统）'};
const sysLight=window.matchMedia('(prefers-color-scheme: light)');
function currentTheme(){return localStorage.getItem(THEME_KEY)||'dark';}
function applyTheme(t){
  const light=t==='light'||(t==='auto'&&sysLight.matches);
  document.body.classList.toggle('light',light);
  $('themeIconMoon').style.display=t==='dark'?'':'none';
  $('themeIconSun').style.display=t==='light'?'':'none';
  $('themeIconAuto').style.display=t==='auto'?'':'none';
  $('themeToggle').title='主题：'+THEME_LABEL[t]+'（点击切换）';
}
sysLight.addEventListener('change',()=>{
  if(currentTheme()==='auto')applyTheme('auto');  // 系统主题变化时实时跟随
});
function toggleTheme(){
  const t=THEME_ORDER[(THEME_ORDER.indexOf(currentTheme())+1)%THEME_ORDER.length];
  applyTheme(t);
  localStorage.setItem(THEME_KEY,t);
  pywebview.api.save_config({theme:t});  // 跨重启持久化
  toast('主题：'+THEME_LABEL[t]);
}
$('themeToggle').onclick=toggleTheme;
applyTheme(currentTheme());  // 同步图标/提示（body class 已在头部脚本应用）
(function(){
