  if(v!=='__custom')$('am_base').value=v;
}
function detectModels(){
  const base=$('am_base').value.trim(), key=$('am_key').value.trim();
  if(!base){toast('请先填 Base URL');return;}
  const btn=$('am_detect_btn'); btn.disabled=true; btn.textContent='识别中…';
  pywebview.api.detect_models(base,key).then(r=>{
    btn.disabled=false; btn.textContent='⟳ 自动识别';
    if(!r.ok){$('am_detect_hint').textContent=r.error;return;}
    $('am_provider').value=r.provider;
    const dl=$('am_models'); dl.innerHTML='';
    r.models.forEach(m=>{const o=document.createElement('option');o.value=m;dl.appendChild(o);});
    if(r.models.length&&!$('am_model').value)$('am_model').value=r.models[0];
    $('am_detect_hint').textContent='已识别 '+r.provider+'，共 '+r.models.length+' 个模型（可点模型框下拉选择）';
  });
}
function addApiModel(){
  const provider=$('am_provider').value.trim(), model=$('am_model').value.trim();
  if(!provider||!model){
    toast('请填写提供方与模型名（或点「自动识别」）'); return;
  }
  pywebview.api.add_api_model(provider,model,$('am_base').value.trim(),
    $('am_key').value.trim()).then(r=>{
    if(!r.ok){toast(r.error);return;}
    toast('已添加 '+provider+' / '+model);
    $('am_model').value=''; loadModelsPage();
  });
}
function copyApiModel(id){
  pywebview.api.copy_api_model(id).then(r=>{
