const TARGETS=[
  ['local:qwen3:8b@ep1','本地 qwen3:8b（免费）'],
  ['api:deepseek-chat','API · DeepSeek'],
  ['api:gpt-4o','API · GPT-4o'],
  ['mix:pool1','聚合池 · 推理增强池'],
  ['mix:pool2','聚合池 · 成本最优池'],
];
function targetLabel(v){
  const t=TARGETS.find(x=>x[0]===v);
  return t?t[1]:v;
}
function initRuleTargets(){
  const sel=$('rl_target');
  TARGETS.forEach(([v,l])=>{
    const o=document.createElement('option');
    o.value=v; o.textContent=l; sel.appendChild(o);
  });
}
function loadRouter(){
  pywebview.api.get_router().then(r=>{
    renderRules(r.rules);
    $('w_cost').value=r.weights.cost; $('w_cost_val').textContent=r.weights.cost;
    $('w_quality').value=r.weights.quality; $('w_quality_val').textContent=r.weights.quality;
    $('w_local').value=r.weights.local_first; $('w_local_val').textContent=r.weights.local_first;
  });
}
function renderRules(rules){
  const el=$('ruleList');
  if(!rules.length){el.innerHTML='<div class="empty">暂无规则，未命中的任务走加权策略</div>';return;}
  el.innerHTML=rules.map((r,i)=>'<div class="mrow2">'+
    '<span style="color:var(--faint);width:20px;text-align:right">'+(i+1)+'</span>'+
    '<span style="font-weight:550">'+esc(r.type)+'</span>'+
    '<span class="pill">'+(r.keywords||[]).map(esc).join('、')+'</span>'+
    '<span style="flex:1"></span>'+
    '<span style="font-size:11.5px;color:var(--muted)">→ '+esc(targetLabel(r.target))+'</span>'+
    '<button class="iconbtn danger" onclick="delRule('+i+')">🗑</button></div>').join('');
}
function addRule(){
  const type=$('rl_type').value.trim();
  const kws=$('rl_keywords').value.split(/[,，]/).map(s=>s.trim()).filter(Boolean);
  if(!type||!kws.length){toast('请填写任务类型与关键词');return;}
  pywebview.api.add_route_rule(type,kws,$('rl_target').value).then(()=>{
    $('rl_type').value=''; $('rl_keywords').value=''; loadRouter();
  });
}
function delRule(i){
  pywebview.api.delete_route_rule(i).then(()=>loadRouter());
}
function weightChanged(){
  const c=+$('w_cost').value,q=+$('w_quality').value,l=+$('w_local').value;
  $('w_cost_val').textContent=c; $('w_quality_val').textContent=q; $('w_local_val').textContent=l;
  pywebview.api.save_weights({cost:c,quality:q,local_first:l});
}
function runSandbox(){
  const text=$('sandbox_input').value.trim(); if(!text)return;
  pywebview.api.route_sandbox(text).then(r=>{
    $('sandboxResult').innerHTML='<div class="sandbox-result">'+
      '<div>命中阶段：<b>'+esc(r.stage)+'</b></div>'+
      '<div>判定类型：'+esc(r.type)+'</div>'+
      '<div>分发目标：<b>'+esc(targetLabel(r.target))+'</b></div>'+
      (r.reason?'<div style="color:var(--faint);font-size:11px">'+esc(r.reason)+'</div>':'')+
      '</div>';
  });
}
