function showEvoProgress(done){
  $('evoProgress').style.display='';
  const row=$('evoPhaseRow'); row.innerHTML='';
  PHASES.forEach(([id,label])=>{
    const st=done.includes(id)?'done':(done.length&&PHASES.findIndex(x=>x[0]===id)===done.length?'doing':'');
    row.innerHTML+='<span class="phase-tag '+st+'">'+(st==='done'?'✓ ':st==='doing'?'● ':'')+label+'</span>';
  });
}
function runEvolution(){
  const btn=$('evoRunBtn'); btn.disabled=true; btn.textContent='运行中…';
  pywebview.api.run_evolution().then(r=>{if(!r.ok){toast(r.error);btn.disabled=false;btn.textContent='🌙 立即运行进化作业';return;}});
  clearInterval(evoPoll);
  evoPoll=setInterval(()=>{
