pywebview.api.register_events(function(type,payload){
  if(type==='delta'){
    if(!curBot)curBot=addMsg('bot','');
    curBot.innerHTML+=esc(payload);
    $('chat').scrollTop=$('chat').scrollHeight;
  }else if(type==='status'){addChip('status',payload);}
  else if(type==='error'){addChip('error',payload);}
  else if(type==='confirm'){showConfirm(payload);}
  else if(type==='task'){upsertTask(payload);}
  else if(type==='done'){
    if(curBot){curBot.innerHTML=render(curBot.textContent);curBot=null;addFeedbackRow();}
