  }else if(t==='status'){
    addChip('status',d.text);
  }else if(t==='confirm'){
    showConfirm(d);
  }else if(t==='lead_plan'){
    $('taskList').innerHTML='';
    (d.tasks||[]).forEach(upsertTask);
