  pywebview.api.get_versions().then(v=>{
    $('verCurrent').innerHTML='<div style="display:flex;align-items:baseline;gap:10px;margin-bottom:9px">'+
      '<b style="font-size:17px">'+esc(v.current.version)+'</b>'+
      '<span style="font-size:11.5px;color:var(--faint)">'+esc(v.current.date)+'</span>'+
      '<span class="pill green">当前版本</span></div>'+
      '<ul style="margin:0;padding-left:18px;font-size:12.5px;color:var(--muted);line-height:2">'+
      v.current.points.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ul>';
    $('verHistory').innerHTML=v.history.map(h=>
      '<div style="padding:9px 0;border-bottom:1px solid var(--border)">'+
      '<div style="display:flex;justify-content:space-between"><b style="font-size:13px">'+esc(h.version)+'</b>'+
