/* ---------- automation ---------- */
function loadAutomation(){
  pywebview.api.get_workflows().then(list=>{
    $('wfEmpty').style.display=list.length?'none':'block';
    $('wfList').innerHTML=list.map(w=>
      '<div class="card wf-card">'+
      '<div style="display:flex;align-items:center;gap:9px">'+
      '<b style="font-size:13.5px">'+esc(w.name)+'</b>'+
      (w.last_ok?'<span class="pill green">上次成功</span>':'<span class="pill red">上次失败</span>')+
      '<span style="flex:1"></span>'+
      '<div class="switch '+(w.enabled?'on':'')+'" onclick="confirmAction(\''+(w.enabled?'停用':'启用')+'任务流 '+esc(w.name)+'\',()=>toggleWf(\''+w.id+'\','+!w.enabled+'),this)"></div></div>'+
      '<div class="wf-desc">'+esc(w.desc)+'</div>'+
      '<div class="wf-meta">'+
      '<span class="badge">'+w.steps.length+' 步</span>'+
      '<div class="cap-chips">'+w.caps.map(c=>'<span>'+esc(c)+'</span>').join('')+'</div></div>'+
      '<button class="btn primary" style="width:100%" onclick="runWf(\''+w.id+'\')">▶ 运行</button></div>'
    ).join('');
  });
}
function toggleWf(id,on){pywebview.api.toggle_workflow(id,on).then(()=>loadAutomation());}
function runWf(id){pywebview.api.run_workflow(id).then(()=>toast('任务流已启动'));}
function openWfDialog(){
  $('wf_name').value='';
  $('wf_steps').innerHTML='';
  addStepRow();
  $('wfDialog').classList.add('open');
}
function addStepRow(){
  const row=document.createElement('div');
  row.className='step-row';
  row.innerHTML='<select><option value="web">web 抓取</option><option value="llm">llm 总结</option>'+
    '<option value="file">file 写盘</option><option value="shell">shell 命令</option></select>'+
    '<input placeholder="参数，如 URL / 提示词 / 路径">'+
    '<button class="btn rm" onclick="this.parentElement.remove()">✕</button>';
  $('wf_steps').appendChild(row);
}
function saveWf(){
  const name=$('wf_name').value.trim();
  if(!name){toast('请填写名称');return;}
  const steps=[...$('wf_steps').querySelectorAll('.step-row')].map(r=>({
    tool:r.querySelector('select').value, arg:r.querySelector('input').value.trim()
  })).filter(s=>s.arg);
  pywebview.api.save_workflow(name,steps).then(()=>{
    $('wfDialog').classList.remove('open'); loadAutomation();
  });
}

