    $('cfg_auto').value=String(c.auto_yes);
    $('cfg_voice').value=String(c.voice_enabled);
    $('cfg_vname').value=c.voice_name;
    $('cfg_workers').value=c.workers_json;
    const dl=$('providers'); dl.innerHTML='';
    st.providers.forEach(p=>{const o=document.createElement('option');o.value=p;dl.appendChild(o);});
    const vd=$('voices'); vd.innerHTML='';
    Object.keys(st.voices).forEach(n=>{const o=document.createElement('option');o.value=n;vd.appendChild(o);});
    $('footProvider').textContent=st.active_label||c.provider;
    // 主题以服务端 desktop.json 为准：覆盖本地缓存，保证重启后不丢设置
    const t=(st.config&&st.config.theme)||'dark';
    storeSet('codeagent-theme',t);
    applyTheme(t);
  });
}

