/* ---------- backend events (pywebview js_api → window) ---------- */
window._onEvent=function(ev){
  switch(ev.kind){
    case 'status': chip('status',ev.text); break;
    case 'text':
      if(!curBot) curBot=addMsg('bot','');
      curBot.innerHTML+=esc(ev.text).replace(/\n/g,'<br>');
      $('chat').scrollTop=1e9; break;
    case 'error': chip('error',ev.text); break;
    case 'done':
      if(curBot){
        curBot.innerHTML=render(curBot.textContent);
        addFeedbackRow(curBot.parentElement);
      }
      curBot=null; setSending(false); break;
    case 'task': upsertTask(ev.task_id,ev.title,ev.status,ev.worker); break;
    case 'worker_text':
      if(curBot) curBot.innerHTML=render(curBot.textContent);
      curBot=addMsg('bot','');
      curBot.innerHTML='<b style="color:var(--muted);font-size:12px">'+(ev.worker||'')+'</b><br>'+esc(ev.text);
      $('chat').scrollTop=1e9; break;
    case 'task_output': {
      const el=document.getElementById('task-'+ev.task_id);
      if(el){
        el.title=ev.text;
        const s=el.querySelector('.t-worker');
        s.textContent=(s.textContent+' ✓').slice(0,30);
      }
      break;
    }
    case 'lead_reply': {
      const d=document.createElement('div');
      d.className='reply-box';
      d.innerHTML=render(ev.text);
      const em=$('taskList').querySelector('.empty'); if(em)em.remove();
      $('taskList').appendChild(d);
      break;
    }
  }
};

