const THEME_NAMES={dark:'深色',light:'浅色',auto:'自动（跟随系统）'};
const _sysLightMq = matchMedia('(prefers-color-scheme: light)');
function getTheme(){ try{ return localStorage.getItem('codeagent-theme')||'dark'; }catch(e){ return 'dark'; } }
function applyThemeMode(mode){
  try{ localStorage.setItem('codeagent-theme',mode); }catch(e){}
  const light = mode==='light' || (mode==='auto' && _sysLightMq.matches);
  document.body.classList.toggle('light',light);
  document.querySelectorAll('#themeTabs .tab').forEach(t=>
    t.classList.toggle('active',t.dataset.theme===mode));
  window.pywebview.api.set_theme(mode).catch(()=>{});
}
try{ _sysLightMq.addEventListener('change',()=>{ if(getTheme()==='auto') applyThemeMode('auto'); }); }catch(e){}
document.querySelectorAll('#themeTabs .tab').forEach(t=>
  t.onclick=()=>{ applyThemeMode(t.dataset.theme);
    toast('主题已切换为「'+THEME_NAMES[t.dataset.theme]+'」'); });

