window._onEvent=function(ev){ switch(ev.kind){
  case 'text': handleToken(ev.text); break;
  case 'replace': ensureAssistant(); curBuf=ev.text; renderAssistant(); break;
  case 'done': endChat(); break;
  case 'error': addChip('错误: '+ev.text,'error'); streaming=false;
    $('sendBtn').disabled=false; break;
  case 'tool_call': handleToolCall(ev); break;
  case 'attachment_action': handleAttachmentAction(ev); break;
  case 'system_notice': addSystemNotice(ev.text); break;
  case 'lead_tasks': setTasks(ev.tasks); break;
  case 'lead_reply': { const el=$('taskList');
    const d=document.createElement('div'); d.className='reply-box';
    d.textContent=ev.text; el.appendChild(d); break; }
} };

